// ============ Tshirt Pre-Order Match + Build Rows ============
// Filter Shopify orders to nerfsg-tshirt-custom-* SKUs and emit one row
// per t-shirt unit (quantity expansion) for the printer handover.

const params = $('Set Parameters').first().json;
const orders = $('Fetch All Orders (paginated)').all().flatMap(p => p.json.orders || []);

// SKU pattern: nerfsg-tshirt-custom-* (with _ <-> - interchangeable, case-insensitive)
const skuRe = /^nerfsg[-_]tshirt[-_]custom[-_].*$/i;
// Title fallback when SKU is missing
const titleRe = /nerfsg.*t.?shirt.*custom/i;

const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fmtDate(d) {
  if (!d || isNaN(d.getTime())) return '';
  return d.getDate() + ' ' + MON[d.getMonth()] + ' ' + d.getFullYear();
}

function getNickname(li) {
  for (const p of (li.properties || [])) {
    if (/^nickname$/i.test(String(p.name || ''))) return String(p.value || '');
  }
  return '';
}

function deriveStatus(o) {
  if (o.cancelled_at) return 'cancelled';
  const fs = String(o.financial_status || '').toLowerCase();
  if (fs === 'refunded') return 'refunded';
  if (fs === 'partially_refunded') return 'partially_refunded';
  if ((o.refunds || []).length > 0) return 'partially_refunded';
  return fs || 'unknown';
}

const out = [];
for (const o of orders) {
  const orderNo = o.order_number != null ? String(o.order_number) : String(o.name || '').replace('#','');
  const dateFmt = fmtDate(new Date(o.created_at));
  const createdMs = new Date(o.created_at).getTime();
  const firstName = (o.customer && o.customer.first_name) || '';
  const lastName  = (o.customer && o.customer.last_name)  || '';
  const shipName  = (o.shipping_address && o.shipping_address.name) || '';
  const customerName = ((firstName + ' ' + lastName).trim()) || shipName || 'Guest';
  const email  = (o.customer && o.customer.email) || o.email || '';
  const status = deriveStatus(o);

  for (const li of (o.line_items || [])) {
    const sku   = String(li.sku || '').trim();
    const title = String(li.title || '').trim();
    const matchSku   = sku && skuRe.test(sku);
    const matchTitle = !sku && titleRe.test(title);
    if (!matchSku && !matchTitle) continue;

    const size     = String(li.variant_title || '').trim();
    const nickname = getNickname(li);
    const qty      = Math.max(1, parseInt(li.quantity || 1, 10));

    for (let i = 0; i < qty; i++) {
      const flags = [];
      if (!nickname) flags.push('EMPTY NICKNAME');
      if (nickname && /[^\x00-\x7F]/.test(nickname)) flags.push('NON-ASCII - verify printer');
      if (status === 'cancelled') flags.push('CANCELLED');
      if (status === 'refunded' || status === 'partially_refunded') flags.push('REFUND - verify');
      if (qty > 1) flags.push('Unit ' + (i+1) + '/' + qty);

      out.push({
        __sortKey: createdMs,
        'Order No.':     orderNo,
        'Order Date':    dateFmt,
        'Customer Name': customerName,
        'Email':         email,
        'SKU':           sku || title,
        'Size':          size,
        'Quantity':      (i+1) + '/' + qty,
        'Nickname':      nickname,
        'Status':        status,
        'Remarks':       flags.join(' | ')
      });
    }
  }
}

// Sort newest-first so the most recent orders are at the top of the sheet
out.sort((a, b) => b.__sortKey - a.__sortKey);
const final = out.map(r => {
  const { __sortKey, ...rest } = r;
  return rest;
});

if (final.length === 0) {
  return [{ json: {
    'Order No.': '',
    'Order Date': '',
    'Customer Name': '',
    'Email': '',
    'SKU': '',
    'Size': '',
    'Quantity': '',
    'Nickname': '',
    'Status': '',
    'Remarks': 'NO TSHIRT PRE-ORDERS in last 60 days'
  } }];
}
return final.map(r => ({ json: r, pairedItem: { item: 0 } }));

// ============ Ensure Tab + Clear (overwrite-each-run pattern) ============
// Sign JWT, ensure dest tab exists (create if missing), clear A:Z, then
// pass through Match items unchanged so the next node (Append) writes them.

const fs = require('fs');
const crypto = require('crypto');
const https = require('https');

function b64u(buf) { return Buffer.from(buf).toString('base64').replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_'); }
function signJWT(saJson, scope) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss: saJson.client_email, scope, aud: 'https://oauth2.googleapis.com/token', exp: now+3600, iat: now };
  const si = b64u(JSON.stringify(header)) + '.' + b64u(JSON.stringify(payload));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(si);
  return si + '.' + b64u(signer.sign(saJson.private_key));
}
function httpsReq(opts, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(opts, res => { let d=''; res.on('data', c => d+=c); res.on('end', () => resolve({ statusCode: res.statusCode, body: d })); });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}
async function getToken(saJson) {
  const jwt = signJWT(saJson, 'https://www.googleapis.com/auth/spreadsheets');
  const body = 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + encodeURIComponent(jwt);
  const r = await httpsReq({ hostname: 'oauth2.googleapis.com', path: '/token', method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) } }, body);
  if (r.statusCode !== 200) throw new Error('token: ' + r.statusCode + ' ' + r.body);
  return JSON.parse(r.body).access_token;
}

const params = $('Set Parameters').first().json;
const sa = JSON.parse(fs.readFileSync($env.N8N_GOOGLE_SA_JSON || '/files/sa.json', 'utf8'));
const tok = await getToken(sa);
const ssId = params.INTERNAL_SHEET_ID;
const tab  = params.DEST_TAB_NAME;

// Get sheet metadata; create tab if missing
const metaR = await httpsReq({ hostname: 'sheets.googleapis.com', path: '/v4/spreadsheets/' + ssId + '?fields=sheets.properties', method: 'GET', headers: { 'Authorization': 'Bearer ' + tok } });
if (metaR.statusCode !== 200) throw new Error('meta: ' + metaR.statusCode + ' ' + metaR.body);
const meta = JSON.parse(metaR.body);
let exists = false;
for (const s of (meta.sheets || [])) if (s.properties && s.properties.title === tab) { exists = true; break; }

if (!exists) {
  const body = JSON.stringify({ requests: [{ addSheet: { properties: { title: tab } } }] });
  const r = await httpsReq({ hostname: 'sheets.googleapis.com', path: '/v4/spreadsheets/' + ssId + ':batchUpdate', method: 'POST', headers: { 'Authorization': 'Bearer ' + tok, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, body);
  if (r.statusCode !== 200) throw new Error('addSheet: ' + r.statusCode + ' ' + r.body);
}

// Clear contents A:Z (overwrite semantics for each run)
const clearPath = '/v4/spreadsheets/' + ssId + '/values/' + encodeURIComponent(tab) + '!A:Z:clear';
const clr = await httpsReq({ hostname: 'sheets.googleapis.com', path: clearPath, method: 'POST', headers: { 'Authorization': 'Bearer ' + tok, 'Content-Length': '0' } }, '');
if (clr.statusCode !== 200) throw new Error('clear: ' + clr.statusCode + ' ' + clr.body);

// Pass through original Match items unchanged so Append writes them
return $input.all();

// ============ Apply Format + Move Tab to Front ============
// Header row (grey + bold), 2 conditional format rules, move tab to leftmost.

const fs = require('fs');
const crypto = require('crypto');
const https = require('https');

function b64u(buf) { return Buffer.from(buf).toString('base64').replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_'); }
function signJWT(saJson, scope) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss: saJson.client_email, scope, aud: 'https://oauth2.googleapis.com/token', exp: now+3600, iat: now };
  const si = b64u(JSON.stringify(header)) + '.' + b64u(JSON.stringify(payload));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(si);
  return si + '.' + b64u(signer.sign(saJson.private_key));
}
function httpsReq(opts, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(opts, res => { let d=''; res.on('data', c => d+=c); res.on('end', () => resolve({ statusCode: res.statusCode, body: d })); });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}
async function getToken(saJson) {
  const jwt = signJWT(saJson, 'https://www.googleapis.com/auth/spreadsheets');
  const body = 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + encodeURIComponent(jwt);
  const r = await httpsReq({ hostname: 'oauth2.googleapis.com', path: '/token', method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) } }, body);
  if (r.statusCode !== 200) throw new Error('token: ' + r.statusCode + ' ' + r.body);
  return JSON.parse(r.body).access_token;
}

const params = $('Set Parameters').first().json;
const sa = JSON.parse(fs.readFileSync($env.N8N_GOOGLE_SA_JSON || '/files/sa.json', 'utf8'));
const tok = await getToken(sa);
const ssId = params.INTERNAL_SHEET_ID;
const tab  = params.DEST_TAB_NAME;

// Get sheetId AND existing CF rules in one call (no ranges filter — that filter
// only returns rules overlapping the cell, which would miss rules anchored to
// row 2+ and cause CF rules to accumulate on each run).
const metaR = await httpsReq({ hostname: 'sheets.googleapis.com', path: '/v4/spreadsheets/' + ssId + '?fields=sheets.properties,sheets.conditionalFormats', method: 'GET', headers: { 'Authorization': 'Bearer ' + tok } });
const meta = JSON.parse(metaR.body);
let sheetId = null;
let existing = [];
for (const s of (meta.sheets || [])) {
  if (s.properties && s.properties.title === tab) {
    sheetId = s.properties.sheetId;
    existing = s.conditionalFormats || [];
    break;
  }
}
if (sheetId === null) throw new Error('Tab not found: ' + tab);

const RED    = { red: 1.0, green: 0.78, blue: 0.78 };
const YELLOW = { red: 1.0, green: 0.94, blue: 0.62 };
const GREY   = { red: 0.85, green: 0.85, blue: 0.85 };
const range  = { sheetId, startRowIndex: 1, startColumnIndex: 0, endColumnIndex: 10 };
const reqs = [];

// Move tab to leftmost
reqs.push({ updateSheetProperties: { properties: { sheetId, index: 0 }, fields: 'index' } });
// Header row formatting (row 1, cols A-J)
reqs.push({ repeatCell: {
  range: { sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: 0, endColumnIndex: 10 },
  cell: { userEnteredFormat: { backgroundColor: GREY, textFormat: { bold: true } } },
  fields: 'userEnteredFormat(backgroundColor,textFormat)'
}});
// Delete existing CF rules (reverse order so indices stay valid)
for (let i = existing.length - 1; i >= 0; i--) {
  reqs.push({ deleteConditionalFormatRule: { sheetId, index: i } });
}
// Rule 0: RED — CANCELLED or REFUND in Remarks (col J = $J2)
reqs.push({ addConditionalFormatRule: { rule: {
  ranges: [range],
  booleanRule: {
    condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=OR(REGEXMATCH($J2,"CANCELLED"),REGEXMATCH($J2,"REFUND"))' }] },
    format: { backgroundColor: RED }
  }
}, index: 0 }});
// Rule 1: YELLOW — NON-ASCII or EMPTY NICKNAME in Remarks
reqs.push({ addConditionalFormatRule: { rule: {
  ranges: [range],
  booleanRule: {
    condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=OR(REGEXMATCH($J2,"NON-ASCII"),REGEXMATCH($J2,"EMPTY NICKNAME"))' }] },
    format: { backgroundColor: YELLOW }
  }
}, index: 1 }});

const body = JSON.stringify({ requests: reqs });
const r = await httpsReq({ hostname: 'sheets.googleapis.com', path: '/v4/spreadsheets/' + ssId + ':batchUpdate', method: 'POST', headers: { 'Authorization': 'Bearer ' + tok, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, body);
if (r.statusCode !== 200) throw new Error('format batchUpdate: ' + r.statusCode + ' ' + r.body);
return [{ json: { status: 'success', tab, sheet_id: sheetId, requests_applied: reqs.length } }];
